import { Router } from 'express';
import { authController } from '../controllers/auth.controller.js';
import { authenticate } from '../middleware/auth.js';
import { validate } from '../middleware/validate.js';
import { registerSchema, loginSchema, refreshTokenSchema, updateProfileSchema, changePasswordSchema, } from '../validators/auth.validator.js';
const router = Router();
router.post('/register', validate({ body: registerSchema }), authController.register.bind(authController));
router.post('/login', validate({ body: loginSchema }), authController.login.bind(authController));
router.post('/refresh', validate({ body: refreshTokenSchema }), authController.refreshToken.bind(authController));
router.post('/logout', authenticate, authController.logout.bind(authController));
router.get('/me', authenticate, authController.getMe.bind(authController));
router.put('/profile', authenticate, validate({ body: updateProfileSchema }), authController.updateProfile.bind(authController));
router.put('/change-password', authenticate, validate({ body: changePasswordSchema }), authController.changePassword.bind(authController));
export default router;
